```cpp
#include <iostream>
#include <fstream>
#include < string >
#include < vector >
#include < sstream >

using namespace std;

int main() {
    // Replace "target" with the specific word you want to search for.
    string target = "target";
    string fileName = "input.txt";

    ifstream file(fileName);
    if (!file) {
        cerr << "Error opening file: " << fileName << endl;
        return 1;
    }

    int count = 0;
    string line;

    while (getline(file, line)) {
        istringstream iss(line);
        string word;
        while (iss >> word) {
            transform(word.begin(), word.end(), word.begin(), ::tolower); // Case-insensitive search
            if (word == target) {
                count++;
                break;
            }
        }
    }

    file.close();

    cout << "The word \"" << target << "\" occurs " << count << " times in the file." << endl;

    return 0;
}
```

Replace `"target"` with the specific word you want to search for in the text file named `"input.txt"`. This program is case-insensitive due to converting all words to lowercase before comparison using `transform()`. The algorithm reads each line, then breaks it down into individual words using a string stream, checks each word against the target term, and increments the counter if there's a match.

